+                        return;
+                    }
+                    _logger.LogInformation("Attempting to acquire license");
+                    _acquireLicenseFunc();
+                    _licenseHeld = true;
+                    UpdateReleaseTimer();
+                    _logger.LogInformation("License acquired successfully");
+                }
+                catch (Exception ex)
+                {
+                    _logger.LogError(ex, "Error acquiring license");
+                    throw;
+                }
+            }
+        }
+
