+{
+  struct nlmsghdr *nlh_recv = (struct nlmsghdr *) recv_buffer;
+  ssize_t len;
+
+  do
+    {
+      len = TEMP_FAILURE_RETRY (recv (sock, recv_buffer, recv_buffer_size, 0));
+      if (len < 0)
+        return crun_make_error (err, errno, "recv");
+  } while (nlh_recv->nlmsg_seq != seq);
