	private void loadPersistedState() {
		filesModel.clear();                         // ← avoid duplication
		FilePersistance
						.getRecentFiles()
						.forEach(item -> {
							var fp = new File(item);
							var path = fp.toPath().toString();
							filesModel.addElement(new ListItem(path, Icons.getIcon("file")));
						});
	}
```

</details>

