<!-- suggestion_start -->

<details>
<summary>📝 Committable suggestion</summary>

> ‼️ **IMPORTANT**
> Carefully review the code before committing. Ensure that it accurately replaces the highlighted code, contains no missing lines, and has no issues with indentation. Thoroughly test & benchmark the code to ensure it meets the requirements.

`````suggestion
export function useWorkflowsV2(
  workflowsQuery: WorkflowsQuery | null,
  swrConfig?: SWRConfiguration
) {
  const api = useApi();
  const queryToPost = workflowsQuery 
    ? {
        ...(workflowsQuery.cel !== undefined && { cel: workflowsQuery.cel }),
        ...(workflowsQuery.limit !== undefined && { limit: workflowsQuery.limit }),
        ...(workflowsQuery.offset !== undefined && { offset: workflowsQuery.offset }),
        ...(workflowsQuery.sortBy !== undefined && { sort_by: workflowsQuery.sortBy }),
        ...(workflowsQuery.sortDir !== undefined && { sort_dir: workflowsQuery.sortDir }),
      }
    : {};

  let requestUrl = "/workflows/query?is_v2=true";

  // Create a stable cache key
  const cacheKey = api.isReady() && workflowsQuery 
    ? [
        requestUrl, 
        queryToPost.cel, 
        queryToPost.limit, 
        queryToPost.offset, 
        queryToPost.sort_by, 
        queryToPost.sort_dir
      ].filter(Boolean).join("::")
    : null;

  const { data, error, isLoading } = useSWR<any>(
    cacheKey,
    () => api.post(requestUrl, queryToPost),
    swrConfig
  );
}
`````

</details>

