+func helpName(fullName string) string {
+	var namePath []string
+	for i, name := range strings.Split(fullName, " ") {
+		namePath = append(namePath, name)
+		if i == 0 {
+			namePath = append(namePath, "[global options]")
+		}
+	}
+
+	if len(namePath) > 1 {
+		fullName = strings.Join(namePath, " ")
+	}
+
+	return fullName
+}
