    /**
     * Retrieves system environment variables after validating the provided secret key.
     * This method provides access to potentially sensitive information and should be
     * secured appropriately.
     *
     * @param secretKey The secret key used to authorize access to environment variables
     * @return An EnvironmentDto containing the system environment variables
     * @throws greencity.exception.exceptions.InvalidSecretKeyException if the secret key is invalid
     */
    @Override
    public EnvironmentDto getEnvironmentVariables(String secretKey) {
        dotenvService.validateSecretKey(secretKey);
        // Log access attempt for security audit
        log.info("Environment variables accessed with valid secretKey");

        // Filter out sensitive environment variables
        Map<String, String> filteredEnv = new HashMap<>(System.getenv());
        // Remove sensitive keys (customize based on your application's needs)
        Arrays.asList("DB_PASSWORD", "JWT_SECRET", "MAIL_PASSWORD", "AWS_SECRET_KEY")
            .forEach(filteredEnv::remove);

        return new EnvironmentDto(filteredEnv);
    }
