+
+    if (isSubmitter && (isOpen || isProcessing)) {
+        return true;
+    }
+
+    const isApprover = isApprovedMember(policy, getCurrentUserAccountID());
+
+    if (isApprover && isProcessing) {
+        return true;
+    }
+
+    const isReportPayer = isPayer(getSession(), report, false, policy);
