+                        $value = stripcslashes($pm[2]);
+                    } elseif (isset($pm[3]) && $pm[3] !== '') {
+                        $value = $pm[3];
+                    } else {
+                        $value = true;
+                    }
+                    // Handle multiple attributes with same name
+                    if (isset($params[$key])) {
+                        if (!is_array($params[$key])) {
+                            $params[$key] = [$params[$key]];
+                        }
+                        $params[$key][] = $value;
+                    } else {
+                        $params[$key] = $value;
+                    }
