+//! Definitions for IPC
+use core::sync::atomic::AtomicBool;
+
+use embassy_sync::{blocking_mutex::raw::RawMutex, channel::Channel, mutex::Mutex};
+
+/// A simple RPC channel for executing commands
+pub struct RpcChannel<M: RawMutex, C, R> {
+    /// Channel for sending commands
+    command: Channel<M, C, 1>,
+    /// Channel for receiving responses
+    response: Channel<M, R, 1>,
+    /// Mutex for synchronizing access to command execution
+    execution_lock: Mutex<M, ()>,
+    handler_created: AtomicBool,
+}
+
+impl<M: RawMutex, C, R> RpcChannel<M, C, R> {
+    /// Create a new RPC channel
+    pub fn new() -> Self {
+        Self {
+            command: Channel::new(),
+            response: Channel::new(),
+            execution_lock: Mutex::new(()),
+            handler_created: AtomicBool::new(false),
+        }
+    }
+
+    /// Create an invoker object that can be used to invoke commands
+    pub fn invoker(&self) -> RpcInvoker<M, C, R> {
+        RpcInvoker::new(self)
+    }
+
+    /// Create a handler object that can be used to execute commands generated by an invoker
+    /// Only one handler can be created
+    pub fn handler(&self) -> Option<RpcHandler<M, C, R>> {
+        if self.handler_created.swap(true, core::sync::atomic::Ordering::SeqCst) {
+            return None;
+        }
+        Some(RpcHandler::new(self))
+    }
+}
+
