+  }
+\cs_new:Nn \__color_parse_model_oklab:nnn
+  {
+    \__color_parse_model_cbrtlms:nnn
+      { \fp_eval:n { #1 + 0.3963377774 * #2 + 0.2158037573 * #3 } }
+      { \fp_eval:n { #1 - 0.1055613458 * #2 - 0.0638541728 * #3 } }
