+                    : route.name;
+
+              const isFocused = focusedName === route.name;
+
+              return (
+                <TabLink
+                  key={route.key}
+                  icon={icons[route.name]}
+                  route={route}
+                  onPress={() => onLinkPressed(isFocused, route)}
