+                  key={route.key}
+                  icon={icons[route.name]}
+                  route={route}
+                  onPress={() => onLinkPressed(isFocused, route)}
+                  label={label}
+                  isFocused={isFocused}
+                />
+              );
+            })}
+          </View>
+        </View>

