+
+namespace KE = Kokkos::Experimental;
+
+using exec_space = Kokkos::DefaultExecutionSpace;
+
+template <class ValueType>
+struct SumFunctor {
+  KOKKOS_INLINE_FUNCTION
+  ValueType operator()(const ValueType& a, const ValueType& b) const {
+    return (a + b);
+  }
+};
+
+template <class ValueType>
+struct MaxFunctor {
+  KOKKOS_INLINE_FUNCTION
+  ValueType operator()(const ValueType& a, const ValueType& b) const {
+    if (a > b)
+      return a;
+    else
+      return b;
+  }
+};
+
+// Helper to obtain last element of a view
+template <class T>
+T obtainLastElem(const Kokkos::View<T*, exec_space>& out) {
+  auto h_out = Kokkos::create_mirror_view(out);
+  Kokkos::deep_copy(h_out, out);
+  auto view_size = h_out.extent(0);
+  return h_out(view_size - 1);
+}
+
+template <class T>
+void InclusiveScan(benchmark::State& state,
+                   const Kokkos::View<T*, exec_space>& in,
+                   Kokkos::View<T*, exec_space>& out) {
+  // Default prefix sum scan
+  Kokkos::Timer timer;
+  KE::inclusive_scan("default scan", exec_space(), KE::cbegin(in), KE::cend(in),
+                     KE::begin(out));
+  exec_space().fence();
+  double time_def = timer.seconds();
+
+  T res_def = obtainLastElem(out);
+
+  // Prefix sum scan using a sum functor
+  SumFunctor<T> sum_functor;
+
+  timer.reset();
+  KE::inclusive_scan("sum functor scan", exec_space(), KE::cbegin(in),
+                     KE::cend(in), KE::begin(out), sum_functor);
+  exec_space().fence();
+  double time_sum_func = timer.seconds();
+
+  T res_sum_func = obtainLastElem(out);
+
+  // Scan using a max functor
+  MaxFunctor<T> max_functor;
+
+  timer.reset();
+  KE::inclusive_scan("max functor scan", exec_space(), KE::cbegin(in),
+                     KE::cend(in), KE::begin(out), max_functor);
+  exec_space().fence();
+  double time_max_func = timer.seconds();
+
+  // Checking expected results
+  std::size_t res_max_func = static_cast<std::size_t>(obtainLastElem(out));
+  std::size_t exp_max_val  = in.size() - 1;
+  bool passed = (res_def == res_sum_func) && (res_max_func == exp_max_val);
+
+  state.counters["Passed"]             = benchmark::Counter(passed);
+  state.counters["Value default scan"] = benchmark::Counter(res_def);
+  state.counters["Value sum functor"]  = benchmark::Counter(res_sum_func);
+  state.counters["Value max functor"]  = benchmark::Counter(res_max_func);
+  state.counters["Time default scan"]  = benchmark::Counter(time_def);
+  state.counters["Time sum functor"]   = benchmark::Counter(time_sum_func);
+  state.counters["Time max functor"]   = benchmark::Counter(time_max_func);
+  state.counters["Size of type"]       = benchmark::Counter(sizeof(T));
+}
+
+template <class T>
+static void Test_InclusiveScan(benchmark::State& state) {
+  const std::size_t kProbSize = state.range(0);
+
+  Kokkos::View<T*, exec_space> in{"input", kProbSize};
+  Kokkos::View<T*, exec_space> out{"output", kProbSize};
+
+  auto h_in = Kokkos::create_mirror_view(in);
+
+  for (std::size_t i = 0; i < kProbSize; ++i) {
+    h_in(i) = i;
+  }
+
+  Kokkos::deep_copy(in, h_in);
+
+  exec_space().fence();
+  for (auto _ : state) {
+    InclusiveScan<T>(state, in, out);
+  }
+}
+
+static constexpr std::size_t PROB_SIZE  = 100'000'000;
+static constexpr std::uint32_t ITER_CNT = 100;
+
+BENCHMARK(Test_InclusiveScan<std::uint64_t>)
+    ->Arg(PROB_SIZE)
+    ->Iterations(ITER_CNT);

