+    }
+
+    public void closeDriver() {
+        if (driver != null) {
+            LOGGER.log(Level.INFO, "Closing WebDriver...");
+            driver.quit();
+            LOGGER.log(Level.INFO, "WebDriver closed.");
+        }
+    }

