```rs
fn group_pools_by_network(resources: &Vec<FeedConfig>) -> HashMap<String, Vec<GeckoTerminalPool>> {
  let mut pools_by_network: HashMap<String, Vec<GeckoTerminalPool>> = HashMap::new();

  for config in resources {
      for pool in &config.arguments {
          let new_pool = {
              let mut cloned_pool = pool.clone();
              cloned_pool.feed_id = config.id.clone();
              cloned_pool
          };

          pools_by_network
              .entry(pool.network.clone())
              .or_insert_with(Vec::new)
              .push(new_pool);
      }
  }

  pools_by_network
}
```

This seems cleaner to me

