+    let mut value: GeckoTerminalMultipleResponce =
+        serde_json::from_str(&string).context("Couldn't parse Gecko terminal response properly")?;
+    for v in value.data.iter_mut() {
+        if let Some(p) = pools
+            .iter()
+            .find(|p| p.pool.to_uppercase() == v.attributes.address.to_uppercase())
+        {
+            v.reverse = p.reverse;
+            v.feed_id = p.feed_id.clone();
+            v.network = network.clone();
+            v.min_volume_usd = p.min_volume_usd;
+        }
     }
+    Ok(value)
 }

