+                            if !res.contains_key(&d.feed_id) {
+                                res.insert(d.feed_id.clone(), vec![]);
+                            }
+                            if let Some(v) = res.get_mut(&d.feed_id) {
+                                v.push(d);
+                            }
+                        }
+                    }
+                    Err(e) => {
+                        println!("Error while fetching ... {e:?}");
+                    }
+                };
+            }
+        }
+    }
+    Ok(res)
+}
