`````suggestion
    private static void InferIfUnset<T>(
        Resource resource,
        Func<Resource, T?> getter,
        Action<Resource, T> setter,
        IEnumerable<IInferenceStrategy<T>> strategies,
        Func<T?, bool> isUnset)
    {
        if (resource is null)     throw new ArgumentNullException(nameof(resource));
        if (getter is null)       throw new ArgumentNullException(nameof(getter));
        if (setter is null)       throw new ArgumentNullException(nameof(setter));
        if (strategies is null)   throw new ArgumentNullException(nameof(strategies));
        if (isUnset is null)      throw new ArgumentNullException(nameof(isUnset));

        if (isUnset(getter(resource)))
        {
            foreach (var strategy in strategies)
            {
                if (strategy.TryInfer(resource, out var value))
                {
                    setter(resource, value);
                    break;
                }
            }
        }
    }
`````

