+<script setup lang="ts">
+import { ref, onMounted } from 'vue';
+import { useRouter } from 'vue-router';
+import { useQuasar } from 'quasar';
+import { alertsService, type InventoryAlert } from 'src/services/alertsService';
+
+const $q = useQuasar();
+const router = useRouter();
+const alerts = ref<InventoryAlert[]>([]);
+const isLoading = ref(false);
+
+// Fetch alerts on component mount
+onMounted(async () => {
+  await fetchAlerts();
+});
+
+/**
+ * Fetches inventory alerts from the service
+ */
+async function fetchAlerts() {
+  try {
+    isLoading.value = true;
+    alerts.value = await alertsService.getInventoryAlerts();
+  } catch (error) {
+    console.error('Error fetching alerts:', error);
+    $q.notify({
+      type: 'negative',
+      message: 'Failed to load inventory alerts',
+      position: 'top',
+      timeout: 3000
+    });
+  } finally {
+    isLoading.value = false;
+  }
+}
+
+/**
+ * Gets the appropriate icon for each category
+ */
+function getAlertIcon(category: string): string {
+  switch (category) {
+    case 'Cabs':
+      return 'directions_car';
+    case 'Accessories':
+      return 'settings_input_component';
+    case 'Materials':
+      return 'category';
+    default:
+      return 'warning';
+  }
+}
+
+/**
+ * Gets the appropriate color for each alert status
+ */
+function getAlertColor(status: string): string {
+  switch (status) {
+    case 'Low Stock':
+      return 'warning';
+    case 'Out of Stock':
+      return 'negative';
+    default:
+      return 'grey';
+  }
+}
+
+/**
+ * Handles the action when an alert is clicked
+ */
+async function handleAlertAction(alert: InventoryAlert) {
+  try {
+    // Navigate to the appropriate inventory page with filter
+    const path = `/inventory/${alert.category.toLowerCase()}`;
+    await router.push({
+      path,
+      query: { status: alert.status.replace(' ', '-').toLowerCase() }
+    });
+    
+    // Show notification
+    $q.notify({
+      type: 'info',
+      message: `Viewing ${alert.status.toLowerCase()} ${alert.category.toLowerCase()}`,
+      position: 'top',
+      timeout: 2000
+    });
+  } catch (error) {
+    console.error('Error handling alert action:', error);
+    $q.notify({
+      type: 'negative',
+      message: 'Failed to process alert action',
+      position: 'top',
+      timeout: 3000
+    });
+  }
+}

