@@ -0,0 +1,84 @@
+//! Definitions for deferred execution of commands
+use core::future::Future;
+
+use embassy_sync::{blocking_mutex::raw::RawMutex, channel::Channel as EmbassyChannel, mutex::Mutex};
+
+/// A simple channel for executing deferred commands
+pub struct Channel<M: RawMutex, C, R> {
+    /// Channel for sending commands
+    command: EmbassyChannel<M, C, 1>,
+    /// Channel for receiving responses
+    response: EmbassyChannel<M, R, 1>,
+    /// Mutex for synchronizing access to command execution
+    execution_lock: Mutex<M, ()>,
+}
+
+impl<M: RawMutex, C, R> Channel<M, C, R> {
+    /// Create a new channel
+    pub const fn new() -> Self {
+        Self {
+            command: EmbassyChannel::new(),
+            response: EmbassyChannel::new(),
+            execution_lock: Mutex::new(()),
+        }
+    }
+
+    /// Create an invoker object that can be used to invoke commands
+    pub fn invoker(&self) -> Invoker<M, C, R> {
+        Invoker::new(self)
+    }
+
+    /// Create a handler object that can be used to execute commands generated by an invoker
+    pub fn handler(&self) -> Handler<M, C, R> {
+        Handler::new(self)
+    }
+}
+
+/// Invoker object for invoking commands
+pub struct Invoker<'a, M: RawMutex, C, R> {
+    inner: &'a Channel<M, C, R>,
+}
+
+impl<'a, M: RawMutex, C, R> Invoker<'a, M, C, R> {
+    /// Create a new invoker object
+    fn new(inner: &'a Channel<M, C, R>) -> Self {
+        Self { inner }
+    }
+
+    /// Invoke a command and return the response
+    /// This locks to ensure that commands are executed atomically
+    pub async fn invoke(&self, command: C) -> R {
+        let _guard = self.inner.execution_lock.lock().await;
+        self.inner.command.send(command).await;
+        self.inner.response.receive().await
+    }
+}
+
+/// Handler object for executing commands generated by an invoker
+pub struct Handler<'a, M: RawMutex, C, R> {
+    inner: &'a Channel<M, C, R>,
+}
+
+impl<'a, M: RawMutex, C, R> Handler<'a, M, C, R> {
+    /// Create a new handler object
+    fn new(inner: &'a Channel<M, C, R>) -> Self {
+        Self { inner }
+    }
+
+    /// Wait for a command
+    pub async fn wait_command(&self) -> C {
+        self.inner.command.receive().await
+    }
+
+    /// Send a response to a command
+    pub async fn send_response(&self, response: R) {
+        self.inner.response.send(response).await;
+    }
+
+    /// Process a command and send a response
+    pub async fn process_command<Fut: Future<Output = R>, F: FnOnce(C) -> Fut>(&self, process: F) {
+        let command = self.wait_command().await;
+        let response = process(command).await;
+        self.send_response(response).await;
+    }

