review_comment:
**Suggestion:** Refactor getLabeledIssues to use a shared axios instance with BASE_URL and timeout, incorporate API-side filtering via the URL, and add pagination support. [API Optimization]
```suggestion
const axiosInstance = axios.create({
  baseURL: BASE_URL,
  timeout: GITHUB_API_TIMEOUT_MS,
  headers: { Authorization: `Bearer ${token}` }
});

/**
 * Fetches open issues that have urgent labels with pagination support
 * @returns {Promise<Array>} - Array of issue objects
 */
async function getLabeledIssues() {
  const url = `/repos/${owner}/${repo}/issues?state=open&labels=urgent`;
  const issues = [];
  let page = 1;
  try {
    let fetched;
    do {
      const res = await axiosInstance.get(`${url}&page=${page}`);
      fetched = res.data;
      issues.push(...fetched);
      page++;
    } while (fetched.length > 0);
    // Exclude pull requests
    return issues.filter(issue => !issue.pull_request);
  } catch (error) {
    console.error(`Error fetching labeled issues: ${error.message}`);
    if (error.response) {
      console.error('API Error:', error.response.status, error.response.statusText);
    }
    throw error;
  }
}
```

