+  useEffect(() => {
+    // Check if user is already authenticated
+    const checkAuthStatus = async () => {
+      const supabase = createClient();
+      const { data: { session } } = await supabase.auth.getSession();
+      if (session) {
+        setIsAlreadyAuthenticated(true);
+      }
