+            message: "Something went wrong. Try again.",
+            style: Toast.Style.Failure,
+          });
+        }
+
+        setIsQuerying(false);
+      },
+      execute: hasCheckedPlugins && hasCheckedPreferences && canExecute && !!searchText,
+      abortable,
+    }
+  );
+
+  // Handle search text and scope changes
+  useEffect(() => {
