+function createActionContainer({ context, elements, uiHandlers, domRefs }) {
+  const { isExtensionRequest, data, currentUser, isStatusPending } = context;
+  const {
+    titleInput,
+    titleInputError,
+    reasonInput,
+    reasonInputError,
+    requestInput,
