+      providesTags: (result, error, arg) => ["FullUser"],
+    }),
+
+    // Update user status
+    updateUserStatus: build.mutation<UserStatus, UserStatusUpdatePayload>({
+      query: (payload) => {
+        return getCommand({
+          method: "user_mod",
+          params: [
+            [payload.userId],
+            {
+              inetuserstatus: [payload.status],
+              version: API_VERSION_BACKUP,
+            },
+          ],
+        });
+      },
