-        if (part == null || part.isEmpty()) {
+        if (part == null || part.isEmpty() || Strings.isBlank(part)) {
             throw new IllegalArgumentException(String.format("%s may not be null or empty", partName));
         }
+        if (!ConfigVariableExpander.KEY_PATTERN.matcher(part).matches()) {
+            logger.warn(String.format("Invalid secret %s name `%s` provided. %s", partName, part, ConfigVariableExpander.KEY_PATTERN_DESCRIPTION));
+        }
         return part.toLowerCase(Locale.US);
     }
