+type GraphElement = {
+  element: HTMLElement;
+  x: number;
+  y: number;
+  height: number;
+  dx: number;
+  dy: number;
+};
+
+function elementsGraph(elements: HTMLElement[], idx: number): GraphElement[] {
+  const { x, y } = elements[idx].getBoundingClientRect();
+  return elements.map((element) => {
+    const { x: eX, y: eY, height: eHeight } = element.getBoundingClientRect();
+    return {
+      element,
+      x: eX,
+      y: eY,
+      height: eHeight,
+      dx: x - eX,
+      dy: y - eY
+    };
+  });
+}
+
