we could change this to List like this - would this be fine?

```
func (c *Controller) getUnavailableVMICount1(pool *poolv1.VirtualMachinePool, vms []*virtv1.VirtualMachine) (int, error) {
    unavailableCount := 0
    
    // Create a map of VM names for quick lookup
    vmMap := make(map[string]struct{})
    for _, vm := range vms {
        vmMap[vm.Name] = struct{}{}
    }

    // Get all VMIs in the namespace
    vmiList, err := c.clientset.VirtualMachineInstance(pool.Namespace).List(context.Background(), metav1.ListOptions{})
    if err != nil {
        return 0, err
    }

    // Count VMIs that belong to VMs in this pool and are not ready
    for _, vmi := range vmiList.Items {
        if _, exists := vmMap[vmi.Name]; exists && !isVMIReady(&vmi) {
            unavailableCount++
        }
    }

    // Count VMs that don't have a VMI (they are considered unavailable)
    for _, vm := range vms {
        found := false
        for _, vmi := range vmiList.Items {
            if vmi.Name == vm.Name {
                found = true
                break
            }
        }
        if !found {
            unavailableCount++
        }
    }

    return unavailableCount, nil
}
